settings.custom_liquid:
{% comment %}
  VANHOUTEN LIVING — FAVORIETEN PAGINA
  Joseph Joseph-inspired layout
  Volledige vervanging van de huidige favorieten Custom Liquid.
  Bestaande localStorage-favorieten blijven werken.
{% endcomment %}

<section class="vhl-wishlist-page">
  <div class="vhl-wishlist-heading">
    <h1>Favorieten</h1>
  </div>

  <div class="vhl-wishlist-divider"></div>

  <div class="vhl-wishlist-note">
    <p>
      Je favorieten worden op dit apparaat bewaard.
      <br>
      Bekijk hieronder de producten die je hebt opgeslagen.
    </p>
  </div>

  <div class="vhl-wishlist-content">
    <div id="vhl-favorites-grid" class="vhl-favorites-grid"></div>

    <div id="vhl-favorites-empty" class="vhl-favorites-empty" hidden>
      <p class="vhl-favorites-empty__title">Je hebt nog geen favorieten.</p>
      <p class="vhl-favorites-empty__text">
        Bewaar producten met het hartje en vind ze hier eenvoudig terug.
      </p>
      <a href="/collections/all" class="vhl-favorites-empty__button">
        Ontdek de collectie
      </a>
    </div>
  </div>
</section>

<style>
  /* Verberg de standaard Shopify paginatitel;
     deze pagina heeft hierboven een eigen Joseph-style titel. */
  .main-page-title,
  .page-title,
  .title--primary {
    display: none !important;
  }

  .vhl-wishlist-page,
  .vhl-wishlist-page * {
    box-sizing: border-box;
  }

  .vhl-wishlist-page {
    width: 100%;
    min-height: 560px;
    margin: 0 !important;
    padding: 0 !important;
    background: #ffffff;
    color: #50504f;
  }

  /* Theme spacing rond de Custom Liquid volledig neutraliseren */
  .shopify-section:has(.vhl-wishlist-page) {
    margin-top: 0 !important;
    padding-top: 0 !important;
  }

  /* =========================================================
     01. TITELBLOK — Joseph-stijl
  ========================================================= */

  .vhl-wishlist-heading {
    display: flex;
    align-items: center;
    justify-content: center;

    min-height: 94px;
    padding: 18px 24px 16px;
  }

  .vhl-wishlist-heading h1 {
    margin: 0;

    color: #4e4e4b;

    font-family: inherit;
    font-size: clamp(32px, 2.45vw, 39px);
    font-weight: 300;
    line-height: 1.08;
    letter-spacing: -0.025em;

    text-align: center;
  }

  .vhl-wishlist-divider {
    width: 100%;
    height: 1px;
    background: #ececea;
  }

  /* =========================================================
     02. SUBTIELE INFO
  ========================================================= */

  .vhl-wishlist-note {
    display: flex;
    justify-content: center;

    padding: 18px 24px 12px;
  }

  .vhl-wishlist-note p {
    max-width: 500px;

    margin: 0;

    color: #777773;

    font-size: 12.5px;
    font-weight: 400;
    line-height: 1.6;

    text-align: center;
  }

  /* =========================================================
     03. FAVORIETEN GRID
  ========================================================= */

  .vhl-wishlist-content {
    width: min(calc(100% - 64px), 1120px);

    margin: 0 auto;
    padding: 12px 0 96px;
  }

  .vhl-favorites-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 380px));

    justify-content: start;
    gap: 48px 30px;

    width: 100%;
    padding-left: 120px;
    box-sizing: border-box;
  }

  .vhl-favorite-card {
    position: relative;
    min-width: 0;
  }

  .vhl-favorite-card__image-wrap {
    position: relative;

    display: block;

    width: 100%;
    aspect-ratio: 1 / 1;

    overflow: hidden;

    background: #f7f7f5;

    text-decoration: none;
  }

  .vhl-favorite-card__image {
    display: block;

    width: 100%;
    height: 100%;

    object-fit: cover;
    object-position: center;

    transition: transform .3s ease;
  }

  .vhl-favorite-card__image-wrap:hover .vhl-favorite-card__image {
    transform: scale(1.015);
  }

  /* =========================================================
     04. VERWIJDERKNOP
  ========================================================= */

  .vhl-favorite-card__remove {
    appearance: none;
    -webkit-appearance: none;

    position: absolute;
    top: 13px;
    right: 13px;
    z-index: 5;

    display: flex;
    align-items: center;
    justify-content: center;

    width: 38px;
    height: 38px;

    margin: 0;
    padding: 0;

    background: rgba(255,255,255,.95);
    color: #50504f;

    border: 0;
    border-radius: 50%;

    box-shadow: none;

    cursor: pointer;

    transition:
      background-color .18s ease,
      transform .18s ease;
  }

  .vhl-favorite-card__remove:hover {
    background: #ffffff;
    transform: scale(1.03);
  }

  .vhl-favorite-card__remove::before,
  .vhl-favorite-card__remove::after {
    content: none !important;
    display: none !important;
  }

  .vhl-favorite-card__remove svg {
    display: block;

    width: 19px;
    height: 19px;

    fill: none;
    stroke: currentColor;
    stroke-width: 1.35;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  /* =========================================================
     05. PRODUCTINFORMATIE
     Joseph: prijs eerst, productnaam daaronder
  ========================================================= */

  .vhl-favorite-card__content {
    padding: 11px 2px 0;
  }

  .vhl-favorite-card__price {
    margin: 0 0 6px;

    color: #50504f;

    font-size: 14px;
    font-weight: 400;
    line-height: 1.35;
  }

  .vhl-favorite-card__title {
    display: block;

    max-width: 95%;

    margin: 0;

    color: #676763;

    text-decoration: none;

    font-size: 13.5px;
    font-weight: 400;
    line-height: 1.45;
  }

  .vhl-favorite-card__title:hover {
    color: #3f3f3d;
    text-decoration: underline;
    text-underline-offset: 3px;
  }

  /* =========================================================
     06. LEGE FAVORIETENLIJST
  ========================================================= */

  .vhl-favorites-empty {
    max-width: 500px;

    margin: 18px auto 0;

    text-align: center;
  }

  .vhl-favorites-empty__title {
    margin: 0 0 7px;

    color: #4e4e4b;

    font-size: 17px;
    font-weight: 400;
    line-height: 1.3;
  }

  .vhl-favorites-empty__text {
    max-width: 410px;

    margin: 0 auto 20px;

    color: #777773;

    font-size: 12.5px;
    font-weight: 400;
    line-height: 1.6;
  }

  .vhl-favorites-empty__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    min-height: 44px;

    padding: 0 24px;

    background: #535351;
    color: #ffffff;

    border-radius: 999px;

    text-decoration: none;

    font-size: 11px;
    font-weight: 600;
    line-height: 1;

    text-transform: uppercase;

    transition: background-color .18s ease;
  }

  .vhl-favorites-empty__button:hover {
    background: #40403f;
  }

  .vhl-favorites-loading {
    grid-column: 1 / -1;

    padding: 55px 0;

    color: #777773;

    text-align: center;
    font-size: 13px;
  }

  /* =========================================================
     07. RESPONSIVE
  ========================================================= */

  @media screen and (max-width: 980px) {
    .vhl-wishlist-content {
      width: min(calc(100% - 36px), 760px);
    }

    .vhl-favorites-grid {
      grid-template-columns: repeat(2, minmax(0, 340px));
      justify-content: center;
      gap: 42px 18px;
      padding-left: 0;
    }
  }

  @media screen and (max-width: 749px) {
    .vhl-wishlist-heading {
      min-height: 86px;
      padding: 20px 18px 16px;
    }

    .vhl-wishlist-heading h1 {
      font-size: 31px;
    }

    .vhl-wishlist-note {
      padding: 24px 20px 16px;
    }

    .vhl-wishlist-note p {
      font-size: 12px;
    }

    .vhl-wishlist-content {
      width: calc(100% - 28px);
      padding: 20px 0 70px;
    }

    .vhl-favorites-grid {
      grid-template-columns: minmax(0, 1fr);
      justify-content: stretch;
      gap: 34px 0;
      padding-left: 0;
    }

    .vhl-favorite-card__remove {
      top: 8px;
      right: 8px;

      width: 36px;
      height: 36px;
    }

    .vhl-favorite-card__remove svg {
      width: 18px;
      height: 18px;
    }

    .vhl-favorite-card__content {
      padding: 11px 4px 0;
    }

    .vhl-favorite-card__price {
      margin-bottom: 6px;
      font-size: 13px;
    }

    .vhl-favorite-card__title {
      font-size: 12.5px;
    }

    .vhl-favorites-empty {
      margin-top: 34px;
    }
  }
</style>

<script>
(function () {
  const STORAGE_PREFIX = 'vhl-favorite-';

  const grid =
    document.getElementById('vhl-favorites-grid');

  const empty =
    document.getElementById('vhl-favorites-empty');

  if (!grid || !empty) return;


  function getFavoriteHandles() {
    const handles = [];

    try {
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);

        if (
          key &&
          key.indexOf(STORAGE_PREFIX) === 0 &&
          localStorage.getItem(key) === 'true'
        ) {
          handles.push(
            key.replace(STORAGE_PREFIX, '')
          );
        }
      }
    } catch (error) {
      console.warn(
        'VANHOUTEN LIVING: favorieten konden niet worden gelezen.',
        error
      );
    }

    return handles;
  }


  function money(cents) {
    const currency =
      window.Shopify &&
      Shopify.currency &&
      Shopify.currency.active
        ? Shopify.currency.active
        : 'EUR';

    try {
      return new Intl.NumberFormat(
        'nl-NL',
        {
          style: 'currency',
          currency: currency
        }
      ).format(
        Number(cents) / 100
      );
    } catch (error) {
      return '€' +
        (Number(cents) / 100)
          .toFixed(2)
          .replace('.', ',');
    }
  }


  function getRootUrl() {
    if (
      window.Shopify &&
      Shopify.routes &&
      Shopify.routes.root
    ) {
      return Shopify.routes.root;
    }

    return '/';
  }


  async function getProduct(handle) {
    const root = getRootUrl();

    const response = await fetch(
      root +
      'products/' +
      encodeURIComponent(handle) +
      '.js'
    );

    if (!response.ok) {
      throw new Error(
        'Product niet gevonden: ' + handle
      );
    }

    return await response.json();
  }


  function updateHeaderFavoriteCount() {
    document.dispatchEvent(
      new CustomEvent('vhl:favorites-updated')
    );
  }


  function removeFavorite(handle, card) {
    try {
      localStorage.removeItem(
        STORAGE_PREFIX + handle
      );
    } catch (error) {}

    if (card) {
      card.remove();
    }

    updateHeaderFavoriteCount();

    const remaining =
      getFavoriteHandles();

    if (remaining.length === 0) {
      grid.innerHTML = '';
      empty.hidden = false;
    }
  }


  function escapeHtml(value) {
    const div =
      document.createElement('div');

    div.textContent =
      value || '';

    return div.innerHTML;
  }


  function createCard(product, handle) {
    const card =
      document.createElement('article');

    card.className =
      'vhl-favorite-card';

    const root =
      getRootUrl();

    const url =
      root +
      'products/' +
      encodeURIComponent(handle);

    let image = '';

    if (product.featured_image) {
      image =
        product.featured_image;
    } else if (
      product.images &&
      product.images.length
    ) {
      image =
        product.images[0];
    }

    card.innerHTML = `
      <a
        class="vhl-favorite-card__image-wrap"
        href="${url}"
        aria-label="${escapeHtml(product.title)}"
      >
        ${
          image
            ? `
              <img
                class="vhl-favorite-card__image"
                src="${image}"
                alt="${escapeHtml(product.title)}"
                loading="lazy"
              >
            `
            : ''
        }
      </a>

      <button
        type="button"
        class="vhl-favorite-card__remove"
        aria-label="Verwijder ${escapeHtml(product.title)} uit favorieten"
      >
        <svg
          viewBox="0 0 24 24"
          aria-hidden="true"
        >
          <path
            d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78z"
          ></path>
        </svg>
      </button>

      <div class="vhl-favorite-card__content">
        <p class="vhl-favorite-card__price">
          ${money(product.price)}
        </p>

        <a
          href="${url}"
          class="vhl-favorite-card__title"
        >
          ${escapeHtml(product.title)}
        </a>
      </div>
    `;

    const removeButton =
      card.querySelector(
        '.vhl-favorite-card__remove'
      );

    removeButton.addEventListener(
      'click',
      function () {
        removeFavorite(
          handle,
          card
        );
      }
    );

    return card;
  }


  async function renderFavorites() {
    const handles =
      getFavoriteHandles();

    if (handles.length === 0) {
      grid.innerHTML = '';
      empty.hidden = false;
      return;
    }

    empty.hidden = true;

    grid.innerHTML =
      '<div class="vhl-favorites-loading">Favorieten laden...</div>';

    const results =
      await Promise.allSettled(
        handles.map(
          handle => getProduct(handle)
        )
      );

    grid.innerHTML = '';

    results.forEach(
      function (result, index) {
        const handle =
          handles[index];

        if (result.status === 'fulfilled') {
          grid.appendChild(
            createCard(
              result.value,
              handle
            )
          );
        } else {
          try {
            localStorage.removeItem(
              STORAGE_PREFIX + handle
            );
          } catch (error) {}
        }
      }
    );

    if (
      grid.children.length === 0
    ) {
      empty.hidden = false;
    }
  }


  renderFavorites();


  window.addEventListener(
    'storage',
    function (event) {
      if (
        event.key &&
        event.key.indexOf(STORAGE_PREFIX) === 0
      ) {
        renderFavorites();
      }
    }
  );
})();
</script>
